# Operations ---
class SWMOperationFailedException(Exception):
    pass


class SWMOperationTimeoutException(Exception):
    pass


# Importer ---
class SWMImporterError(Exception):
    pass


class BuildNotFoundInTemp(SWMImporterError):
    pass


class InvalidMD5Checksum(SWMImporterError):
    pass


class BuildDeletionFailed(SWMImporterError):
    pass


class UploadFailed(SWMImporterError):
    pass


class FileIsBeingUploaded(SWMImporterError):
    pass
